1218|      {
1219|         png_app_error(png_ptr, "no unknown chunk support on read");
1220|
1221|         return;
1222|      }
1223|#  endif
1224|#  if !defined(PNG_WRITE_UNKNOWN_CHUNKS_SUPPORTED) && \
1225|      defined(PNG_WRITE_SUPPORTED)
1226|      if ((png_ptr->mode & PNG_IS_READ_STRUCT) == 0)
1227|      {
